      "module": "Mathlib.Data.Finsupp.Weight"
    },
    {
      "name": "Finsupp.le_weight_of_ne_zero'",
      "type": " {σ : Type u_1} {M : Type u_4} [AddCommMonoid M] [PartialOrder M] [IsOrderedAddMonoid M] [CanonicallyOrderedAdd M] (w : σ → M) {s : σ} {f : σ →₀ ℕ} (hs : f s ≠ 0) : w s ≤ (Finsupp.weight w) f",
      "module": "Mathlib.Data.Finsupp.Weight"
    },
    {
      "name": "Finsupp.le_weight_of_ne_zero",
      "type": " {σ : Type u_1} {M : Type u_2} [AddCommMonoid M] [PartialOrder M] [IsOrderedAddMonoid M] {w : σ → M} (hw : ∀ (s : σ), 0 ≤ w s) {s : σ} {f : σ →₀ ℕ} (hs : f s ≠ 0) : w s ≤ (Finsupp.weight w) f",
      "module": "Mathlib.Data.Finsupp.Weight"
    },
    {
      "name": "MvPolynomial.le_weightedTotalDegree",
      "type": " {R : Type u_1} {M : Type u_2} [CommSemiring R] {σ : Type u_3} [AddCommMonoid M] [SemilatticeSup M] [OrderBot M] (w : σ → M) {φ : MvPolynomial σ R} {d : σ →₀ ℕ} (hd : d ∈ φ.support) : (Finsupp.weight w) d ≤ MvPolynomial.weightedTotalDegree w φ",
      "module": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous"
    },
    {
      "name": "MvPowerSeries.weightedOrder_le",
      "type": " {σ : Type u_1} {R : Type u_2} [Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {d : σ →₀ ℕ} (h : (MvPowerSeries.coeff d) f ≠ 0) : MvPowerSeries.weightedOrder w f ≤ ↑((Finsupp.weight w) d)",
      "module": "Mathlib.RingTheory.MvPowerSeries.Order"
    },
    {
      "name": "MvPowerSeries.le_weightedOrder",
      "type": " {σ : Type u_1} {R : Type u_2} [Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {n : ℕ∞} (h : ∀ (d : σ →₀ ℕ), ↑((Finsupp.weight w) d) < n → (MvPowerSeries.coeff d) f = 0) : n ≤ MvPowerSeries.weightedOrder w f",
      "module": "Mathlib.RingTheory.MvPowerSeries.Order"
    },
    {
      "name": "MvPowerSeries.nat_le_weightedOrder",
      "type": " {σ : Type u_1} {R : Type u_2} [Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {n : ℕ} (h : ∀ (d : σ →₀ ℕ), (Finsupp.weight w) d < n → (MvPowerSeries.coeff d) f = 0) : ↑n ≤ MvPowerSeries.weightedOrder w f",
      "module": "Mathlib.RingTheory.MvPowerSeries.Order"
    },
    {
      "name": "MvPowerSeries.le_weightedOrder_subst",
      "type": " {σ : Type u_1} {R : Type u_3} [CommRing R] {τ : Type u_4} {S : Type u_5} [CommRing S] [Algebra R S] {a : σ → MvPowerSeries τ S} (w : τ → ℕ) (ha : MvPowerSeries.HasSubst a) (f : MvPowerSeries σ R) : ⨅ d, ⨅ (_ : (MvPowerSeries.coeff d) f ≠ 0), (Finsupp.weight (MvPowerSeries.weightedOrder w ∘ a)) d ≤ MvPowerSeries.weightedOrder w (MvPowerSeries.subst a f)",
      "module": "Mathlib.RingTheory.MvPowerSeries.Substitution"
    }
  ]
